import"./modulepreload-polyfill-B5Qt9EMX.js";/* empty css              */import{t}from"./toast-Cexsccug.js";const n=document.getElementById("register-form");n.addEventListener("submit",async r=>{r.preventDefault();const a={email:document.getElementById("email").value.trim(),password:document.getElementById("password").value,first_name:document.getElementById("first_name").value.trim(),last_name:document.getElementById("last_name").value.trim(),phone:document.getElementById("phone").value.trim()};try{const e=await(await fetch("http://localhost:3000/api/auth/register",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify(a)})).json();if(!e.success){t.error(e.error);return}t.success(e.message),setTimeout(()=>{window.location.href="login.html"},1e3)}catch{t.error("Server error. Please try again later.")}});
